#! /usr/bin/env node
/**
 * 用已安装的 dsh-ppt 脚本生成 5 页教学 deck 并做真实校验。
 * 只调用已安装的 scripts/deck-core.mjs（不安装任何依赖）。
 */
import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync, existsSync, statSync } from 'node:fs'
import { resolve } from 'node:path'

const OUT = '/workspace/skill-closure/community/deck'
const SKILL = '/opt/evimed/skills/community/dsh-ppt'

const { buildDeck } = await import(resolve(SKILL, 'scripts/deck-core.mjs'))

const title = 'Library Study Seats: A Bounded Structural Check'

// 题面要求的 5 页，顺序固定：scenario, incentives, uncertainty, reversible experiment, evaluation
const slides = [
  {
    layout: 'cover',
    kicker: 'Bounded teaching case',
    title: '100 shared study seats, first-come booking',
    subtitle: 'Structural analysis of access asymmetry, incentives and a reversible fair-booking test',
  },
  {
    layout: 'bullets',
    kicker: '01 · Scenario',
    title: 'A booking time is not the same for everyone',
    bullets: [
      '100 shared seats, first-come reservations, no extra capacity',
      'Booking opens at library opening; no-shows occupy some seats',
      'One group can book at opening; the other is in compulsory class',
      'Seats run out before the second group is free to book',
      'No individual may be identified, so only seat- and period-level counting is possible',
    ],
  },
  {
    layout: 'bullets',
    kicker: '02 · Incentives',
    title: 'Booking costs nothing to hold',
    bullets: [
      'Who decides (booking at opening), who pays (those excluded), who gains (the holder) are three different people',
      'Holding a seat has no cost; releasing it brings the holder nothing',
      'The gain is immediate and private; the cost is delayed and lands on someone else',
      'Access rule quietly turns free time into the entry ticket',
      'No one has to intend harm — this is what the rule rewards',
    ],
  },
  {
    layout: 'bullets',
    kicker: '03 · Uncertainty',
    title: 'What is not actually known',
    bullets: [
      'No measured no-show rate exists — this case gives structural facts only',
      'Not confirmed: the time clash causes it, or demand is simply lower for the second group',
      'Not confirmed: no-shows are motive-driven, or cancelling is just too much friction',
      'Both rival readings stay open; they are not equally weighted, and not yet excluded',
      'The harmed side stops trying, so its demand disappears from the record',
    ],
  },
  {
    layout: 'bullets',
    kicker: '04 · Reversible experiment',
    title: 'Two switchable changes, no new seats',
    bullets: [
      'Condition A: release part of the 100 seats only in the after-class window, ranking rule untouched',
      'Condition B: after booking, one tap to confirm still needed; unconfirmed seats return to the pool',
      'Individuals cannot be identified, so conditions alternate by week block, not by person',
      'Measure only: seat-hours actually used per period, unused seat-hours from bookings, booking requests per period',
      'Any change reverts within one day; stop if identities or added capacity become necessary',
    ],
  },
  {
    layout: 'bullets',
    kicker: '05 · Evaluation',
    title: 'Decide in advance how the test is read',
    bullets: [
      'Success: more seat-hours actually used at peak, with no extra step for anyone',
      'If both changes show little movement, the time-clash account weakens and must be redone',
      'Results are read as evidence about competing explanations, not as a score for a group',
      'Null results are reported, not dropped',
      'Roll back at once if the confirmation step pushes new time cost onto the same group',
    ],
  },
]

const result = buildDeck({
  title,
  slides,
  theme: 'data',
  lang: 'en',
  outputDir: OUT,
  fileName: 'study-seats-5-slides',
})

console.log('buildDeck ok, slideCount =', result.slideCount)

// ---------------- 真实校验 ----------------
const checks = []
const sha256 = (p) => createHash('sha256').update(readFileSync(p)).digest('hex')

const pptx = result.pptxPath
const html = result.htmlPath
const jsonP = result.jsonPath
for (const p of [pptx, html, jsonP]) {
  checks.push({ check: 'file exists: ' + p.split('/').pop(), pass: existsSync(p) && statSync(p).size > 0, detail: existsSync(p) ? statSync(p).size + ' bytes' : 'missing' })
}

// 1) PPTX = PK zip header
const head = readFileSync(pptx).subarray(0, 2).toString('latin1')
checks.push({ check: 'PPTX PK header', pass: head === 'PK', detail: 'first two bytes = ' + JSON.stringify(head) })

// 2) ppt/presentation.xml 在包里
let listing = ''
try {
  listing = execFileSync('unzip', ['-l', pptx], { encoding: 'utf8' })
  checks.push({ check: 'unzip -l exit 0', pass: true, detail: 'entries: ' + (listing.trim().split('\n').length - 3) })
} catch (err) {
  checks.push({ check: 'unzip -l exit 0', pass: false, detail: 'ERROR: ' + String(err.message) })
}
checks.push({ check: 'ppt/presentation.xml present', pass: /ppt\/presentation\.xml/.test(listing), detail: (listing.match(/[^\n]*presentation\.xml[^\n]*/g) || ['none']).join(' | ') })
const slideParts = (listing.match(/ppt\/slides\/slide\d+\.xml/g) || [])
checks.push({ check: 'slides in package', pass: slideParts.length === 5, detail: slideParts.join(', ') || 'none' })

// 3) HTML5 slides
const htmlText = readFileSync(html, 'utf8')
checks.push({ check: 'HTML5 doctype', pass: /^<!DOCTYPE html>/.test(htmlText.trim()), detail: htmlText.slice(0, 15) })
const slideEls = htmlText.match(/<section class="slide[^"]*"/g) || []
checks.push({ check: 'HTML slide sections == 5', pass: slideEls.length === 5, detail: slideEls.length + ' sections' })
checks.push({ check: 'HTML self-contained (no external src/href)', pass: !/<(script|link)[^>]+(src|href)=/i.test(htmlText), detail: 'inline assets only' })

// 4) manifest 与幻灯片内容一致，且无截断
const manifest = JSON.parse(readFileSync(jsonP, 'utf8'))
checks.push({ check: 'manifest slideCount == 5', pass: manifest.slideCount === 5, detail: JSON.stringify({ theme: manifest.theme, language: manifest.language, slideCount: manifest.slideCount }) })
const echoed = manifest.slides.every((s, i) => {
  const wanted = slides[i].title
  const okTitle = s.title === wanted
  const okBullets = (s.bullets ?? []).length === ((slides[i].bullets ?? []).length)
  const okLayout = s.layout === slides[i].layout
  return okTitle && okBullets && okLayout
})
checks.push({ check: 'manifest titles/bullets/layouts untruncated', pass: echoed, detail: manifest.slides.map((s) => s.layout + ':' + (s.bullets ?? []).length).join(' ') })
const order = manifest.slides.map((s) => s.kicker).join(' | ')
checks.push({ check: 'kicker order scenario→evaluation', pass: /Scenario[\s\S]*Incentives[\s\S]*Uncertainty[\s\S]*Reversible experiment[\s\S]*Evaluation/.test(order), detail: order })
const bulletRange = manifest.slides.every((s) => (s.bullets ?? []).length === 0 || ((s.bullets ?? []).length >= 1 && (s.bullets ?? []).length <= 8))
checks.push({ check: 'bullets per slide within 1-8', pass: bulletRange, detail: manifest.slides.map((s) => (s.bullets ?? []).length).join(',') })

// 5) 内容抽查：关键文本确实落在产物里
const mustAppear = ['compulsory class', 'switchable', 'unconfirmed', 'reverts within one day', 'Null results']
checks.push({ check: 'key phrases present in HTML', pass: mustAppear.every((m) => htmlText.includes(m)), detail: mustAppear.map((m) => m + '=' + htmlText.includes(m)).join(', ') })

const receipts = {
  script: 'build-deck.mjs (dsh-ppt CLI)',
  scriptPath: resolve(SKILL, 'scripts/build-deck.mjs'),
  corePath: resolve(SKILL, 'scripts/deck-core.mjs'),
  builder: 'deck-core.mjs buildDeck()',
  fileName: result.fileName,
  theme: manifest.theme,
  language: manifest.language,
  slideCount: manifest.slideCount,
  bytes: { html: statSync(html).size, pptx: statSync(pptx).size, json: statSync(jsonP).size },
  sha256: { html: sha256(html), pptx: sha256(pptx), json: sha256(jsonP) },
  checks,
  passed: checks.filter((c) => c.pass).length,
  failed: checks.filter((c) => !c.pass).length,
}
writeFileSync(resolve(OUT, 'build-receipt.json'), JSON.stringify(receipts, null, 2) + '\n', 'utf8')

for (const c of checks) console.log((c.pass ? 'PASS  ' : 'FAIL  ') + c.check + '  ::  ' + c.detail)
console.log('\npassed=' + receipts.passed + ' failed=' + receipts.failed)
process.exitCode = receipts.failed === 0 ? 0 : 1

