// ---- 最小 zip 读取器（仅依赖 node:zlib；环境没有 unzip 命令，也不安装任何包）----
function readZipCentralDirectory(buf) {
  // 定位 EOCD 签名 0x06054b50
  let eocd = -1
  for (let i = buf.length - 22; i >= 0; i -= 1) {
    if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break }
  }
  if (eocd < 0) throw new Error('zip: EOCD not found')
  const count = buf.readUInt16LE(eocd + 10)
  let off = buf.readUInt32LE(eocd + 16)
  const out = []
  for (let i = 0; i < count; i += 1) {
    if (buf.readUInt32LE(off) !== 0x02014b50) throw new Error('zip: bad central directory header at ' + off)
    const method = buf.readUInt16LE(off + 10)
    const compSize = buf.readUInt32LE(off + 20)
    const nameLen = buf.readUInt16LE(off + 28)
    const extraLen = buf.readUInt16LE(off + 30)
    const commentLen = buf.readUInt16LE(off + 32)
    const localOff = buf.readUInt32LE(off + 42)
    const name = buf.subarray(off + 46, off + 46 + nameLen).toString('utf8')
    out.push({ name, method, compSize, localOff })
    off += 46 + nameLen + extraLen + commentLen
  }
  return out
}

function readZipEntry(buf, entry) {
  if (!entry) return ''
  const lo = entry.localOff
  if (buf.readUInt32LE(lo) !== 0x04034b50) throw new Error('zip: bad local header for ' + entry.name)
  const nameLen = buf.readUInt16LE(lo + 26)
  const extraLen = buf.readUInt16LE(lo + 28)
  const start = lo + 30 + nameLen + extraLen
  const raw = buf.subarray(start, start + entry.compSize)
  return (entry.method === 0 ? raw : inflateRawSync(raw)).toString('utf8')
}

